    /// <summary>
    /// Returns the joining type of <paramref name="codePoint"/>.
    /// </summary>
    public static JoiningType TypeOf(int codePoint)
    {
        int low = 0, high = Types.Length - 1;
        while (low <= high)
        {
            int mid = (low + high) >> 1;
            if (Types[mid].Last < codePoint) low = mid + 1;
            else if (Types[mid].First > codePoint) high = mid - 1;
            else return Types[mid].Type;
        }
        if (codePoint is < 0 or > 0x10FFFF or (>= 0xD800 and <= 0xDFFF)) return JoiningType.NonJoining;
        return CharUnicodeInfo.GetUnicodeCategory(codePoint) is UnicodeCategory.NonSpacingMark or UnicodeCategory.EnclosingMark or UnicodeCategory.Format
            ? JoiningType.Transparent
            : JoiningType.NonJoining;
    }

